FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    location    "system";
    object      fvSchemes;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

fluxScheme      HLLC;

ddtSchemes
{
    default         Euler;
    timeIntegrator  RK2SSP;
}

gradSchemes
{
    default         cellMDLimited leastSquares 1;
}

divSchemes
{
    default         none;
    div(tauMC)      Gauss linear;
    div(alphaRhoPhi.RDX,lambda.RDX) Riemann;
}

laplacianSchemes
{
    default         Gauss linear corrected;
}

interpolationSchemes
{
    default             cubic;
    reconstruct(alpha)  vanLeer;
    reconstruct(rho)    vanLeer;
    reconstruct(U)      vanLeerV;
    reconstruct(e)      vanLeer;
    reconstruct(p)      vanLeer;
    reconstruct(c)      vanLeer;
    reconstruct(speedOfSound) vanLeer;
    "reconstruct\(lambda.*\)" vanLeer;
}

snGradSchemes
{
    default         corrected;
}


